package com.aetherforge.service;
import com.aetherforge.repo.KnowledgeRepository;import org.springframework.stereotype.Service;import org.springframework.web.multipart.MultipartFile;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;
@Service public class KnowledgeService {private final KnowledgeRepository repo;public KnowledgeService(KnowledgeRepository r){repo=r;}public void upload(String factoryId,MultipartFile f)throws Exception{if(f.isEmpty()||f.getSize()>10_000_000)throw new IllegalArgumentException("Invalid or oversized document");String c=new String(f.getBytes(),StandardCharsets.UTF_8);repo.addDocument(factoryId,f.getOriginalFilename()==null?"upload":f.getOriginalFilename(),f.getContentType()==null?"text/plain":f.getContentType(),c);var docs=repo.documents();String docId=String.valueOf(docs.get(0).get("id"));int i=0;for(int p=0;p<c.length();p+=1200){String chunk=c.substring(p,Math.min(c.length(),p+1200));repo.addChunk(docId,i++,chunk,embedding(chunk));}}private String embedding(String x){try{var md=MessageDigest.getInstance("SHA-256");var h=md.digest(x.getBytes(StandardCharsets.UTF_8));var a=new double[16];for(int i=0;i<a.length;i++)a[i]=(h[i]&255)/255.0;return java.util.Arrays.toString(a);}catch(Exception e){return "[]";}}public List<Map<String,Object>> search(String q){return repo.search(q);}public List<Map<String,Object>> docs(){return repo.documents();}}
